682	/// Keeps `engine` as this thread's engine for the module `inner`, stamped
683	/// as the most recently used, and evicts past `ENGINES_PER_THREAD`.
684	pub(crate) fn adopt(inner: &Arc<Inner>, engine: Engine) {
685	    let (dead, evicted) = ENGINES.with(|engines| {
686	        let mut engines = engines.borrow_mut();
687	        let dead = sweep(&mut engines.map);
688	        engines.uses += 1;
689	        let stamp = engines.uses;
690	        engines
691	            .map
692	            .insert(inner.id, (Arc::downgrade(inner), stamp, engine));
693	        let evicted = evict(&mut engines.map);
694	        (dead, evicted)
695	    });
696	    drop(dead);
697	    drop(evicted);
698	}
