700	/// Runs `f` on this thread's engine for `module`, building it by `load`
701	/// when this thread has none. The map is not borrowed while `f` runs.
702	fn with_engine<T>(
703	    module: &Module,
704	    budget_ms: u64,
705	    f: impl FnOnce(&mut Engine) -> Result<T, Diagnostic>,
706	) -> Result<T, Diagnostic> {
707	    let inner = module.inner();
708	    let (dead, found) = ENGINES.with(|engines| {
709	        let mut engines = engines.borrow_mut();
710	        let dead = sweep(&mut engines.map);
711	        let found = engines.map.remove(&inner.id);
712	        (dead, found)
713	    });
714	    drop(dead);
715	    let mut engine = match found {
716	        Some((_, _, engine)) => engine,
717	        None => {
718	            let mut engine = Engine::new(module.library())?;
719	            engine.load(module.name(), module.source(), budget_ms)?;
720	            engine
721	        }
722	    };
723	    let answer = f(&mut engine);
724	    adopt(inner, engine);
725	    answer
726	}
