728	/// Runs `module`'s `render` at `frame` with `props` laid over its schema
729	/// (G-4) and `ctx`, under a deadline of `budget_ms`. `Ok` is the SVG text
730	/// and the warnings of THIS call, each stamped with `frame`.
731	pub fn svg(
732	    module: &Module,
733	    frame: i64,
734	    props: &serde_json::Value,
735	    ctx: &serde_json::Value,
736	    budget_ms: u64,
737	) -> Result<(String, Vec<Diagnostic>), Diagnostic> {
738	    if !ctx.is_object() {
739	        let mut d = Diagnostic::error("ctx must be a JSON object");
740	        d.frame = Some(frame);
741	        return Err(d);
742	    }
743	    let (merged, mut warnings) = overlay(module.schema(), props);
744	    let (text, sink) = with_engine(module, budget_ms, |engine| {
745	        engine.call(module.name(), frame, &merged, ctx, budget_ms)
746	    })
747	    .map_err(|mut d| {
748	        // A load on a thread with no engine yet fails here too; its
749	        // sentence already says "while loading", and it still gets a frame.
750	        d.frame.get_or_insert(frame);
751	        d
752	    })?;
753	    warnings.extend(sink.into_iter().map(Diagnostic::warning));
754	    for w in &mut warnings {
755	        w.frame = Some(frame);
756	    }
757	    Ok((text, warnings))
758	}
