776	/// The pending exception of `e` as a Diagnostic; line and column from
777	/// `stack`, preferring a frame in the module `name`.
778	pub(crate) fn diagnose(
779	    ctx: &rquickjs::Ctx<'_>,
780	    e: rquickjs::Error,
781	    name: &str,
782	    frame: Option<i64>,
783	) -> Diagnostic {
784	    let mut d = Diagnostic::error(e.to_string());
785	    d.frame = frame;
786	    if !matches!(e, rquickjs::Error::Exception) {
787	        return d;
788	    }
789	    let caught = ctx.catch();
790	    let mut stack = None;
791	    if let Some(exception) = caught.as_exception() {
792	        let kind: Option<String> = exception.get("name").ok();
793	        let message = exception.message().unwrap_or_default();
794	        d.message = match kind {
795	            Some(kind) if !kind.is_empty() => format!("{kind}: {message}"),
796	            _ => message,
797	        };
798	        stack = exception.stack();
799	    } else if let Some(text) = caught.as_string().and_then(|s| s.to_string().ok()) {
800	        d.message = text;
801	    } else {
802	        d.message = format!("threw {}", caught.type_name());
803	    }
804	    if let Some((line, column)) = stack.as_deref().and_then(|s| position(s, name)) {
805	        d.line = Some(line);
806	        d.column = Some(column);
807	    }
808	    d
809	}
