811	/// The `L:C` of the first stack frame whose file ends with `name`, else of
812	/// the first frame (quickjs-ng writes `    at render (<name>:L:C)`; the
813	/// standard library and the sandbox are `eval_script`).
814	pub(crate) fn position(stack: &str, name: &str) -> Option<(u32, u32)> {
815	    let mut first = None;
816	    for line in stack.lines() {
817	        let trimmed = line.trim().trim_end_matches(')');
818	        let mut parts = trimmed.rsplitn(3, ':');
819	        let (Some(col), Some(row), Some(rest)) = (parts.next(), parts.next(), parts.next()) else {
820	            continue;
821	        };
822	        let (Ok(col), Ok(row)) = (col.parse::<u32>(), row.parse::<u32>()) else {
823	            continue;
824	        };
825	        if rest.ends_with(name) {
826	            return Some((row, col));
827	        }
828	        first.get_or_insert((row, col));
829	    }
830	    first
831	}
