833	/// `d` in the budget's words when the call's deadline had passed. An
834	/// interrupt's position is the function's, and the sentence says so.
835	pub(crate) fn budgeted(mut d: Diagnostic, expired: bool, budget_ms: u64) -> Diagnostic {
836	    if !expired {
837	        return d;
