850	/// The SVG text `render` returned at `frame`, or the sentence naming what
851	/// came back instead; a string over `SVG_BYTES` is refused by its length.
852	pub(crate) fn returned_svg(value: Value<'_>, frame: i64) -> Result<String, Diagnostic> {
853	    let message = if let Some(text) = value.as_string() {
854	        match text.to_string() {
855	            Ok(text) if text.len() > SVG_BYTES => format!(
856	                "render returned {} bytes at frame {frame}; the SVG may be at most {SVG_BYTES} bytes",
857	                text.len()
858	            ),
859	            Ok(text) if text.starts_with("<svg") => return Ok(text),
860	            Ok(text) => {
861	                let head: String = text.chars().take(40).collect();
862	                format!(
863	                    "render returned a string that does not start with <svg at frame {frame}: {head:?}"
864	                )
865	            }
866	            Err(_) => format!(
867	                "render's string could not be read at frame {frame} — is it tens of megabytes?"
868	            ),
869	        }
870	    } else if value.is_undefined() {
871	        format!("render returned undefined at frame {frame} — did you forget `return`?")
872	    } else {
873	        // rquickjs names numbers `int` and `float`; an author knows `number`.
874	        let kind = match value.type_name() {
875	            "int" | "float" => "number",
876	            "bool" => "boolean",
877	            other => other,
878	        };
879	        format!("render returned {kind} at frame {frame}; it must return an SVG string")
880	    };
881	    let mut d = Diagnostic::error(message);
882	    d.frame = Some(frame);
883	    Err(d)
884	}
