75	//! A graphic's module, compiled once (road map 10 §5c): its source, its
76	//! revision (G-13), the `meta` and `schema` it exported, read out as
77	//! JSON in the module's own key order, and the warnings its top level
78	//! raised while compiling (G-21 (b)). A `Module` holds no QuickJS object,
79	//! so it is `Send + Sync`; each thread that draws it keeps its own engine.
80	
81	use std::sync::atomic::{AtomicU64, Ordering};
82	use std::sync::Arc;
83	
84	use sha2::{Digest, Sha256};
85	
86	use crate::diagnostic::Diagnostic;
87	use crate::library::Library;
88	use crate::props::{check_schema, colour_defaults, overlay};
89	use crate::runtime::{adopt, Engine};
90	
91	static NEXT_ID: AtomicU64 = AtomicU64::new(1);
92	
93	/// A compiled graphic module. Cloning it is cheap; the engines drawing it
94	/// are swept once every clone has been dropped.
95	#[derive(Clone)]
96	pub struct Module {
97	    inner: Arc<Inner>,
98	}
99	
100	pub(crate) struct Inner {
101	    pub(crate) id: u64,
102	    name: String,
103	    source: String,
104	    revision: String,
105	    meta: serde_json::Value,
106	    schema: serde_json::Value,
107	    library: Arc<Library>,
108	    warnings: Vec<Diagnostic>,
109	}
110	
111	impl Module {
112	    /// Evaluates `source` as the ES module `name` on the calling thread,
113	    /// under a deadline of `budget_ms`, and checks what it exports: a
114	    /// `render` function, a `meta` object and a well-formed `schema`.
115	    pub fn compile(
116	        library: Arc<Library>,
117	        name: &str,
118	        source: &str,
119	        budget_ms: u64,
120	    ) -> Result<Module, Diagnostic> {
121	        let revision: String = Sha256::digest(source.as_bytes())
122	            .iter()
123	            .map(|b| format!("{b:02x}"))
124	            .collect();
125	        let mut engine = Engine::new(&library)?;
126	        let exports = engine.load(name, source, budget_ms)?;
127	        let texts = colour_defaults(&exports.schema);
128	        let ok = engine.parse_colours(&texts, budget_ms);
129	        check_schema(&exports.schema, &|t| {
130	            texts.iter().zip(&ok).any(|(s, k)| *k && s == t)
131	        })?;
132	        if !exports.meta.is_object() {
133	            return Err(Diagnostic::error("meta must be an object"));
134	        }
135	        let inner = Arc::new(Inner {
136	            id: NEXT_ID.fetch_add(1, Ordering::Relaxed),
137	            name: name.to_string(),
138	            source: source.to_string(),
139	            revision,
140	            meta: exports.meta,
141	            schema: exports.schema,
142	            library,
143	            warnings: exports
144	                .warnings
145	                .into_iter()
146	                .map(Diagnostic::warning)
147	                .collect(),
148	        });
149	        adopt(&inner, engine);
150	        Ok(Module { inner })
151	    }
152	
153	    pub(crate) fn inner(&self) -> &Arc<Inner> {
154	        &self.inner
155	    }
156	
157	    pub fn name(&self) -> &str {
158	        &self.inner.name
159	    }
160	
161	    pub fn source(&self) -> &str {
162	        &self.inner.source
163	    }
164	
165	    /// SHA-256 of the source's bytes, 64 lowercase hex digits (G-13).
166	    pub fn revision(&self) -> &str {
167	        &self.inner.revision
168	    }
169	
170	    /// The exported `meta`, `{}` when there is none.
171	    pub fn meta(&self) -> &serde_json::Value {
172	        &self.inner.meta
173	    }
174	
175	    /// The exported `schema`, `{}` when there is none.
176	    pub fn schema(&self) -> &serde_json::Value {
177	        &self.inner.schema
178	    }
179	
180	    /// The warnings the module's top level raised while compiling, in
181	    /// order. Each has `Level::Warning` and `frame`, `line` and `column`
182	    /// set to None (spec §11 G-21 (b)).
183	    pub fn warnings(&self) -> &[Diagnostic] {
184	        &self.inner.warnings
185	    }
186	
187	    pub fn library(&self) -> &Arc<Library> {
188	        &self.inner.library
189	    }
190	
191	    /// The schema's defaults, key by key.
192	    pub fn defaults(&self) -> serde_json::Value {
193	        overlay(&self.inner.schema, &serde_json::json!({})).0
194	    }
195	}
196	//! A module's schema and the props drawn with it (road map 10 §5c, G-4):
197	//! the schema is checked strictly when a module compiles; stored props are
198	//! laid over it leniently at render time, every surprise a warning.
199	
200	use serde_json::{Map, Value};
201	
202	use crate::diagnostic::Diagnostic;
203	
204	/// The most keys a module's schema may declare (G-4). The core restates it
205	/// as `GRAPHIC_MAX_PROPS`, since G-2 forbids importing it there;
206	/// `core/tests/graphic_ffi.rs`'s `one_max_props_in_the_engine_and_the_core`
207	/// pins the two, and `tests/reference.rs` pins the number the reference states.
208	pub const MAX_PROPS: usize = 64;
209	/// The most options an `enum` entry may list (G-4). The core restates it as
210	/// `GRAPHIC_MAX_OPTIONS`, pinned in `core/tests/graphic_ffi.rs`.
211	pub const MAX_OPTIONS: usize = 32;
212	/// The most characters a `string` entry's default may hold (G-4). The core
213	/// restates it as `GRAPHIC_MAX_STRING`, pinned in `core/tests/graphic_ffi.rs`.
214	pub const MAX_STRING: usize = 4096;
215	/// A schema entry's six types, in the order the refusal lists them (G-4). The
216	/// core restates it as `GRAPHIC_TYPES`, pinned in `core/tests/graphic_ffi.rs`.
217	pub const TYPES: [&str; 6] = ["string", "number", "boolean", "color", "enum", "asset"];
218	
219	/// §5c's rules for a schema, each refused in its own sentence. `colour`
220	/// answers whether G-12 takes a `color` entry's default (spec §11 G-25).
221	pub(crate) fn check_schema(
222	    schema: &Value,
223	    colour: &dyn Fn(&str) -> bool,
224	) -> Result<(), Diagnostic> {
225	    let Some(entries) = schema.as_object() else {
226	        return Err(Diagnostic::error("schema must be an object"));
227	    };
228	    if entries.len() > MAX_PROPS {
229	        return Err(Diagnostic::error(format!(
230	            "schema has {} keys; the most is {MAX_PROPS}",
231	            entries.len()
232	        )));
233	    }
234	    for (key, entry) in entries {
235	        check_entry(key, entry, colour).map_err(Diagnostic::error)?;
236	    }
237	    Ok(())
238	}
239	
240	/// Each string `default` of a `type: "color"` entry, in schema order — what
241	/// `check_schema`'s `colour` is asked about. Checks nothing else.
242	pub(crate) fn colour_defaults(schema: &Value) -> Vec<String> {
243	    let Some(entries) = schema.as_object() else {
244	        return Vec::new();
245	    };
246	    entries
247	        .values()
248	        .filter(|entry| entry.get("type").and_then(Value::as_str) == Some("color"))
249	        .filter_map(|entry| entry.get("default").and_then(Value::as_str))
250	        .map(str::to_string)
251	        .collect()
252	}
253	
254	fn check_entry(key: &str, entry: &Value, colour: &dyn Fn(&str) -> bool) -> Result<(), String> {
255	    if !is_name(key) {
256	        return Err(format!(
257	            "schema key \"{key}\" is not a name (letters, digits and _, starting with a letter or _, at most 32 characters)"
258	        ));
259	    }
260	    let Some(kind) = entry.get("type").and_then(Value::as_str) else {
261	        return Err(format!("schema.{key} must be an object with a type"));
262	    };
263	    if !TYPES.contains(&kind) {
264	        return Err(format!(
265	            "schema.{key}.type \"{kind}\" is not one of string, number, boolean, color, enum, asset"
266	        ));
267	    }
268	    if kind == "enum" {
269	        let good = entry
270	            .get("options")
271	            .and_then(Value::as_array)
272	            .is_some_and(|o| {
273	                (1..=MAX_OPTIONS).contains(&o.len()) && o.iter().all(Value::is_string)
274	            });
275	        if !good {
276	            return Err(format!("schema.{key}.options must be 1–32 strings"));
277	        }
278	    }
279	    let Some(default) = entry.get("default") else {
280	        return Err(format!("schema.{key} has no default"));
281	    };
282	    let fits = match kind {
283	        "string" => default
284	            .as_str()
285	            .is_some_and(|s| s.chars().count() <= MAX_STRING),
286	        "color" => default.as_str().is_some_and(colour),
287	        _ => fits(kind, entry, default),
288	    };
289	    if !fits {
290	        return Err(format!("schema.{key}.default {default} is not a {kind}"));
291	    }
292	    if let Some(animate) = entry.get("animate").filter(|a| !a.is_boolean()) {
293	        return Err(format!("schema.{key}.animate {animate} is not a boolean"));
294	    }
295	    Ok(())
296	}
297	
298	fn is_name(key: &str) -> bool {
299	    let mut chars = key.chars();
300	    let head = chars
301	        .next()
302	        .is_some_and(|c| c.is_ascii_alphabetic() || c == '_');
303	    head && key.len() <= 32 && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
304	}
305	
306	/// Whether `value` is of the entry's `kind` (render time: a string's length
307	/// is not checked).
308	fn fits(kind: &str, entry: &Value, value: &Value) -> bool {
309	    match kind {
310	        "string" | "color" => value.is_string(),
311	        "number" => value.as_f64().is_some_and(f64::is_finite),
312	        "boolean" => value.is_boolean(),
313	        "enum" => options(entry).contains(value),
314	        "asset" => value.is_string() || value.is_null(),
315	        _ => false,
316	    }
317	}
318	
319	fn options(entry: &Value) -> Vec<Value> {
320	    entry
321	        .get("options")
322	        .and_then(Value::as_array)
323	        .cloned()
324	        .unwrap_or_default()
325	}
326	
327	/// `stored` laid over the schema's defaults, in the schema's key order,
328	/// then the stored keys the schema lacks, passed through. Never refuses:
329	/// every key that did not fit is the default plus a warning. An `asset`
330	/// stored as `""` is "no image" and is handed to `render` as `null`, with
331	/// no warning (spec §11 G-42).
332	pub fn overlay(schema: &Value, stored: &Value) -> (Value, Vec<Diagnostic>) {
333	    let mut warnings = Vec::new();
334	    let empty = Map::new();
335	    let stored = match stored {
336	        Value::Object(map) => map,
337	        other => {
338	            warnings.push(Diagnostic::warning(format!(
339	                "props is {}, not an object; the defaults are used",
340	                kind_of(other)
341	            )));
342	            &empty
343	        }
344	    };
345	    let entries = schema.as_object().cloned().unwrap_or_default();
346	    let mut props = Map::new();
347	    for (key, entry) in &entries {
348	        let default = entry.get("default").cloned().unwrap_or(Value::Null);
349	        let kind = entry.get("type").and_then(Value::as_str).unwrap_or("");
350	        let value = match stored.get(key) {
351	            None => default,
352	            // "No image" (G-42): an asset stored as `""` reaches `render` as `null`.
353	            Some(Value::String(text)) if kind == "asset" && text.is_empty() => Value::Null,
354	            Some(value) if fits(kind, entry, value) => value.clone(),
355	            Some(value) if kind == "enum" && value.is_string() => {
356	                warnings.push(Diagnostic::warning(format!(
357	                    "props.{key} = {value} is not one of {}; the default {default} is used",
358	                    Value::from(options(entry))
359	                )));
360	                default
361	            }
362	            Some(value) => {
363	                warnings.push(Diagnostic::warning(format!(
364	                    "props.{key} is {} but the schema says {kind}; the default {default} is used",
365	                    kind_of(value)
366	                )));
367	                default
368	            }
369	        };
370	        props.insert(key.clone(), value);
371	    }
372	    for (key, value) in stored {
373	        if !entries.contains_key(key) {
374	            warnings.push(Diagnostic::warning(format!(
375	                "props.{key} is not in the schema; it is passed through"
376	            )));
377	            props.insert(key.clone(), value.clone());
378	        }
379	    }
380	    (Value::Object(props), warnings)
381	}
382	
383	fn kind_of(value: &Value) -> &'static str {
384	    match value {
385	        Value::String(_) => "a string",
386	        Value::Number(_) => "a number",
387	        Value::Bool(_) => "a boolean",
388	        Value::Null => "null",
389	        Value::Array(_) => "an array",
390	        Value::Object(_) => "an object",
391	    }
392	}
393	//! One QuickJS runtime and context per (thread, module) — the `Engine` —
394	//! the thread's map of them, and `svg`, the one call that runs a module's
395	//! `render` (road map 10 §5b).
396	//!
397	//! A runtime never leaves the thread that made it: the map is a
398	//! `thread_local!`, keyed by the module's id, and an entry whose `Module`
399	//! has been dropped everywhere is swept before the next call on that
400	//! thread. The map holds at most `ENGINES_PER_THREAD` engines: each is
401	//! stamped with a use counter when it is adopted, and the least recently
402	//! used past the cap are evicted after the call, to be loaded again on
403	//! their next frame (spec §11 G-21 (a)). What `__warn` collects while a
404	//! module's top level evaluates is drained by `load` (G-21 (b)). The
405	//! deadline is the ONE clock in the crate's `src/`: it stops a call that
406	//! runs too long and feeds no pixel.
407	
408	use std::cell::RefCell;
409	use std::collections::HashMap;
410	use std::rc::Rc;
411	use std::sync::{Arc, Mutex, Weak};
412	use std::time::{Duration, Instant};
413	
414	use rquickjs::{Context, Function, Module as JsModule, Persistent, Runtime, Value};
415	
416	use crate::diagnostic::Diagnostic;
417	use crate::exception::{budgeted, diagnose, returned_svg};
418	use crate::host;
419	use crate::library::Library;
420	use crate::module::{Inner, Module};
421	use crate::props::overlay;
422	use crate::sandbox::{NoImports, SANDBOX};
423	
424	/// §5b's heap limit per runtime.
425	pub const HEAP_BYTES: usize = 64 << 20;
426	/// §5b's stack limit per runtime.
427	pub const STACK_BYTES: usize = 1 << 20;
428	/// The most SVG `render` may answer, in bytes (spec §11 G-20 (c)).
429	pub const SVG_BYTES: usize = 8 << 20;
430	/// The most engines one thread holds (spec §11 G-21 (a)).
431	pub const ENGINES_PER_THREAD: usize = 16;
432	
433	const STDLIB: &str = include_str!("stdlib.js");
434	const NOISE: &str = include_str!("noise.js");
435	const PATH: &str = include_str!("path.js");
436	
437	/// A loaded module's `meta` and `schema`, as JSON, and what `__warn`
438	/// collected while its top level evaluated, in order.
439	pub(crate) struct Exports {
440	    pub(crate) meta: serde_json::Value,
441	    pub(crate) schema: serde_json::Value,
442	    pub(crate) warnings: Vec<String>,
443	}
444	
445	/// Fields drop in DECLARATION order: the saved `render` before its
446	/// context, the context before its runtime — the reverse aborts in
447	/// QuickJS's `JS_FreeRuntime` (§5b).
448	pub(crate) struct Engine {
449	    render: Option<Persistent<Function<'static>>>,
450	    warnings: Rc<RefCell<Vec<String>>>,
451	    deadline: Arc<Mutex<Option<Instant>>>,
452	    context: Context,
453	    #[allow(dead_code)] // held, never read: it must outlive `context`
454	    runtime: Runtime,
455	}
456	
457	/// The module, the use stamp of the entry's last adoption, its engine.
458	type Entry = (Weak<Inner>, u64, Engine);
459	
460	/// This thread's engines by module id, and the use counter that stamps
461	/// them — a count of adoptions, not a clock.
462	#[derive(Default)]
463	struct Engines {
464	    map: HashMap<u64, Entry>,
465	    uses: u64,
466	}
467	
468	thread_local! {
469	    static ENGINES: RefCell<Engines> = RefCell::new(Engines::default());
470	}
471	
472	fn engine_error(e: rquickjs::Error) -> Diagnostic {
473	    Diagnostic::error(format!("the engine could not start: {e}"))
474	}
475	
476	impl Engine {
477	    /// A runtime with §5b's limits, the host functions, the standard
478	    /// library and the sandbox — in that order, with no deadline.
479	    pub(crate) fn new(library: &Arc<Library>) -> Result<Engine, Diagnostic> {
480	        let runtime = Runtime::new().map_err(engine_error)?;
481	        runtime.set_memory_limit(HEAP_BYTES);
482	        runtime.set_max_stack_size(STACK_BYTES);
483	        let deadline: Arc<Mutex<Option<Instant>>> = Arc::new(Mutex::new(None));
484	        let watched = deadline.clone();
485	        runtime.set_interrupt_handler(Some(Box::new(
486	            move || matches!(*crate::library::lock(&watched), Some(at) if Instant::now() > at),
487	        )));
488	        runtime.set_loader(NoImports, NoImports);
489	        let context = Context::full(&runtime).map_err(engine_error)?;
490	        let warnings = Rc::new(RefCell::new(Vec::new()));
491	        context.with(|ctx| -> Result<(), Diagnostic> {
492	            host::install(&ctx, library, warnings.clone())?;
493	            for (name, script) in [
494	                ("stdlib.js", STDLIB),
495	                ("noise.js", NOISE),
496	                ("path.js", PATH),
497	                ("sandbox", SANDBOX),
498	            ] {
499	                ctx.eval::<(), _>(script)
500	                    .map_err(|e| diagnose(&ctx, e, name, None))?;
501	            }
502	            Ok(())
503	        })?;
504	        Ok(Engine {
505	            render: None,
506	            warnings,
507	            deadline,
508	            context,
509	            runtime,
510	        })
511	    }
512	
513	    /// Sets the deadline `budget_ms` from now and clears the warning sink.
514	    fn arm(&self, budget_ms: u64) {
515	        self.warnings.borrow_mut().clear();
516	        *crate::library::lock(&self.deadline) =
517	            Some(Instant::now() + Duration::from_millis(budget_ms));
518	    }
519	
520	    /// Clears the deadline; answers whether it had passed.
521	    fn disarm(&self) -> bool {
522	        let mut slot = crate::library::lock(&self.deadline);
523	        let expired = matches!(*slot, Some(at) if Instant::now() > at);
524	        *slot = None;
525	        expired
526	    }
527	
528	    /// Declares and evaluates `source` as the ES module `name`, unwrapped,
529	    /// keeps its `render`, and answers its `meta` and `schema` (`{}` when
530	    /// not exported) and the warnings its top level raised.
531	    pub(crate) fn load(
532	        &mut self,
533	        name: &str,
534	        source: &str,
535	        budget_ms: u64,
536	    ) -> Result<Exports, Diagnostic> {
537	        self.render = None;
538	        self.arm(budget_ms);
539	        let answer = self.context.with(|ctx| {
540	            let module = JsModule::declare(ctx.clone(), name, source)
541	                .map_err(|e| diagnose(&ctx, e, name, None))?;
542	            let (module, promise) = module.eval().map_err(|e| diagnose(&ctx, e, name, None))?;
543	            promise
544	                .finish::<()>()
545	                .map_err(|e| diagnose(&ctx, e, name, None))?;
546	            let render: Function = module
547	                .get("render")
548	                .map_err(|_| Diagnostic::error("the module exports no `render` function"))?;
549	            let meta = export_json(&ctx, &module, "meta");
550	            let schema = export_json(&ctx, &module, "schema");
551	            Ok((Persistent::save(&ctx, render), (meta, schema)))
552	        });
553	        let expired = self.disarm();
554	        match answer {
555	            Ok((render, (meta, schema))) => {
556	                self.render = Some(render);
557	                let warnings = self.warnings.borrow_mut().drain(..).collect();
558	                Ok(Exports {
559	                    meta,
560	                    schema,
561	                    warnings,
562	                })
563	            }
564	            Err(d) => Err(budgeted(d, expired, budget_ms)),
565	        }
566	    }
567	
568	    /// Whether the standard library's `__parseColour` takes each of `texts`
569	    /// (G-12), under ONE deadline of `budget_ms`: a throw, or a call the
570	    /// deadline had already passed, is false (spec §11 G-25). Stores nothing.
571	    pub(crate) fn parse_colours(&self, texts: &[String], budget_ms: u64) -> Vec<bool> {
572	        self.arm(budget_ms);
573	        let answer = self.context.with(|ctx| {
574	            let parse: Option<Function> = ctx.globals().get("__parseColour").ok();
575	            texts
576	                .iter()
577	                .map(|text| {
578	                    let deadline = *crate::library::lock(&self.deadline);
579	                    let late = deadline.is_some_and(|at| Instant::now() > at);
580	                    let Some(parse) = parse.as_ref().filter(|_| !late) else {
581	                        return false;
582	                    };
583	                    let taken = parse.call::<_, Value>((text.as_str(),)).is_ok();
584	                    if !taken {
585	                        let _ = ctx.catch();
586	                    }
587	                    taken
588	                })
589	                .collect()
590	        });
591	        self.disarm();
592	        answer
593	    }
594	
595	    /// One call of `render(frame, props, ctx)`; answers the SVG text and
596	    /// the warnings `__warn` collected during it.
597	    fn call(
598	        &mut self,
599	        name: &str,
600	        frame: i64,
601	        props: &serde_json::Value,
602	        ctx: &serde_json::Value,
603	        budget_ms: u64,
604	    ) -> Result<(String, Vec<String>), Diagnostic> {
605	        let render = self
606	            .render
607	            .clone()
608	            .ok_or_else(|| Diagnostic::error("the module exports no `render` function"))?;
609	        self.arm(budget_ms);
610	        let answer = self.context.with(|js| -> Result<String, Diagnostic> {
611	            let at = Some(frame);
612	            let render = render
613	                .restore(&js)
614	                .map_err(|e| diagnose(&js, e, name, at))?;
615	            let props = js
616	                .json_parse(props.to_string())
617	                .map_err(|e| diagnose(&js, e, name, at))?;
618	            let context = js
619	                .json_parse(ctx.to_string())
620	                .map_err(|e| diagnose(&js, e, name, at))?;
621	            let value: Value = render
622	                .call((frame as f64, props, context))
623	                .map_err(|e| diagnose(&js, e, name, at))?;
624	            returned_svg(value, frame)
625	        });
626	        let expired = self.disarm();
627	        let svg = answer.map_err(|d| budgeted(d, expired, budget_ms))?;
628	        let warnings = self.warnings.borrow_mut().drain(..).collect();
629	        Ok((svg, warnings))
630	    }
631	}
