652	/// Removes this thread's entries whose module has been dropped everywhere,
653	/// and answers them so the caller drops them outside the map's borrow.
654	fn sweep(map: &mut HashMap<u64, Entry>) -> Vec<Entry> {
655	    let dead: Vec<u64> = map
656	        .iter()
657	        .filter(|(_, (weak, _, _))| weak.strong_count() == 0)
658	        .map(|(id, _)| *id)
659	        .collect();
660	    dead.into_iter().filter_map(|id| map.remove(&id)).collect()
661	}
662	
663	/// Removes the least recently used entries while the map holds more than
664	/// `ENGINES_PER_THREAD`, and answers them so the caller drops them outside
665	/// the map's borrow. The entry adopted last holds the highest stamp, so it
666	/// is never one of them.
667	fn evict(map: &mut HashMap<u64, Entry>) -> Vec<Entry> {
668	    let mut evicted = Vec::new();
669	    while map.len() > ENGINES_PER_THREAD {
670	        let oldest = map
671	            .iter()
672	            .min_by_key(|(_, (_, stamp, _))| *stamp)
673	            .map(|(id, _)| *id);
674	        match oldest.and_then(|id| map.remove(&id)) {
675	            Some(entry) => evicted.push(entry),
676	            None => break,
677	        }
678	    }
679	    evicted
680	}
681	
682	/// Keeps `engine` as this thread's engine for the module `inner`, stamped
683	/// as the most recently used, and evicts past `ENGINES_PER_THREAD`.
684	pub(crate) fn adopt(inner: &Arc<Inner>, engine: Engine) {
685	    let (dead, evicted) = ENGINES.with(|engines| {
686	        let mut engines = engines.borrow_mut();
687	        let dead = sweep(&mut engines.map);
688	        engines.uses += 1;
689	        let stamp = engines.uses;
690	        engines
691	            .map
692	            .insert(inner.id, (Arc::downgrade(inner), stamp, engine));
693	        let evicted = evict(&mut engines.map);
694	        (dead, evicted)
695	    });
696	    drop(dead);
697	    drop(evicted);
698	}
699	
700	/// Runs `f` on this thread's engine for `module`, building it by `load`
701	/// when this thread has none. The map is not borrowed while `f` runs.
702	fn with_engine<T>(
703	    module: &Module,
704	    budget_ms: u64,
705	    f: impl FnOnce(&mut Engine) -> Result<T, Diagnostic>,
706	) -> Result<T, Diagnostic> {
707	    let inner = module.inner();
708	    let (dead, found) = ENGINES.with(|engines| {
709	        let mut engines = engines.borrow_mut();
710	        let dead = sweep(&mut engines.map);
711	        let found = engines.map.remove(&inner.id);
712	        (dead, found)
713	    });
714	    drop(dead);
715	    let mut engine = match found {
716	        Some((_, _, engine)) => engine,
717	        None => {
718	            let mut engine = Engine::new(module.library())?;
719	            engine.load(module.name(), module.source(), budget_ms)?;
720	            engine
721	        }
722	    };
723	    let answer = f(&mut engine);
724	    adopt(inner, engine);
725	    answer
726	}
