833	/// `d` in the budget's words when the call's deadline had passed. An
834	/// interrupt's position is the function's, and the sentence says so.
835	pub(crate) fn budgeted(mut d: Diagnostic, expired: bool, budget_ms: u64) -> Diagnostic {
836	    if !expired {
837	        return d;
838	    }
839	    d.message = match (d.frame, d.line, d.column) {
840	        (None, _, _) => format!("over the {budget_ms} ms budget while loading ({})", d.message),
841	        (Some(f), Some(l), Some(c)) => format!(
842	            "over the {budget_ms} ms budget at frame {f} ({}); {l}:{c} is where the function begins, not the statement that ran long",
843	            d.message
844	        ),
845	        (Some(f), _, _) => format!("over the {budget_ms} ms budget at frame {f} ({})", d.message),
846	    };
847	    d
848	}
