994	/// Installs the four globals on `ctx`. `sink` collects `__warn`'s
995	/// messages for the engine that owns it.
996	pub(crate) fn install(
997	    ctx: &rquickjs::Ctx<'_>,
998	    library: &Arc<Library>,
999	    sink: Rc<RefCell<Vec<String>>>,
1000	) -> Result<(), Diagnostic> {
1001	    let fonts = library.clone();
1002	    // No lock is held here around `measure_text`: its memo lock lives in
1003	    // `library.rs` and is taken only for the memo's own read and write.
1004	    let measure = Function::new(
1005	        ctx.clone(),
1006	        move |text: String,
1007	              family: String,
1008	              size: f64,
1009	              weight: f64,
1010	              style: String,
1011	              letter_spacing: f64,
1012	              xml_space: String| {
1013	            // Seven parameters: rquickjs 0.14's `FromParams` maximum.
1014	            let preserve_space = match xml_space.as_str() {
1015	                "default" => false,
1016	                "preserve" => true,
1017	                other => {
1018	                    let message = format!(
1019	                        "measureText: xmlSpace must be \"default\" or \"preserve\", not \"{other}\""
1020	                    );
1021	                    return serde_json::json!({ "error": message }).to_string();
1022	                }
1023	            };
1024	            let font = TextFont {
1025	                family,
1026	                size,
1027	                weight: weight as u16,
1028	                style: match style.as_str() {
1029	                    "italic" => FontStyle::Italic,
1030	                    "oblique" => FontStyle::Oblique,
1031	                    _ => FontStyle::Normal,
1032	                },
1033	                letter_spacing,
1034	                preserve_space,
1035	            };
1036	            match measure_text(&fonts, &text, &font) {
1037	                Ok(metrics) => metrics.to_json().to_string(),
1038	                Err(d) => serde_json::json!({ "error": d.message }).to_string(),
1039	            }
1040	        },
1041	    )
1042	    .map_err(host_error)?;
1043	    let assets = library.clone();
1044	    let names = Function::new(ctx.clone(), move || {
1045	        serde_json::Value::from(assets.asset_names()).to_string()
1046	    })
1047	    .map_err(host_error)?;
1048	    let warn = Function::new(ctx.clone(), move |message: String| {
1049	        sink.borrow_mut().push(message);
1050	    })
1051	    .map_err(host_error)?;
1052	    let colour = Function::new(ctx.clone(), named_colour).map_err(host_error)?;
