1	//! The two graphic ops (road map 10's G2a): `add_graphic_clip`, which
2	//! places a clip drawn by a module in the package, and `set_graphic`, which
3	//! patches what it is drawn from.
4	//!
5	//! What a graphic IS — its fields, the name rule, the side bound, the
6	//! schema and props checks and the colour normalisation — is
7	//! `model_graphic.rs`'s, and this module only composes them into ops. The
8	//! placement tail is `edit_described.rs`'s `add_described_clip`, the one every
9	//! sourceless clip is placed through, so a graphic clip obeys the overlap
10	//! rule and the default five seconds exactly as a text or shape clip does.
11	//!
12	//! **Every argument is checked before the placement tail runs**, name
13	//! first, so an op the table's bound probe sends reaches the side check on
14	//! any project, whatever its tracks.
15	//!
16	//! The core never reads a module (it has no filesystem), so the `schema`
17	//! a `props` patch is checked against arrives WITH the op (G-4). Without
18	//! one — a replayed op, a caller that has none — only the shape is
19	//! checked.
20	//!
21	//! `set_graphic` merges `props` key by key into the stored map: `insert`
22	//! keeps an existing key's slot and appends a new one, and `null` removes
23	//! with `shift_remove`, which keeps the other keys' order (`Map::remove`
24	//! would swap the last key into the hole). `Project ==` cannot see an
25	//! order change, so the Identity arm is unaffected either way, and only
26	//! the written text shows it. With a `schema`, a `null` for a prop an
27	//! action on the clip names stores the schema's default instead (spec §11
28	//! G-34 (d)): the action's ramp keeps a start.
29	
30	use serde_json::{Map, Value};
31	
32	use crate::actions_graphic::names_prop;
33	use crate::edit_action_graphic::schema_default;
34	use crate::edit_described::Described;
35	use crate::export::describe;
36	use crate::model::{GraphicProps, Project, Source};
37	use crate::model_graphic::{
38	    check_count, check_name, check_props, check_schema, check_side, GRAPHIC_MAX_SIDE,
39	};
40	use crate::outcome::Outcome;
41	use crate::patch::unknown_key;
42	use crate::time::Ticks;
43	
44	/// One read `set_graphic` patch: each field `None` when its key was absent.
45	struct GraphicPatch {
46	    name: Option<String>,
47	    width: Option<u32>,
48	    height: Option<u32>,
49	    /// The outer `Option` is "was the key given"; the inner is what to
50	    /// store, `None` for a `null`, which gives the length back to the
51	    /// clip's duration.
52	    length: Option<Option<Ticks>>,
53	    /// Checked and normalised, `null`s kept as removals.
54	    props: Option<Map<String, Value>>,
55	}
56	
57	impl Project {
58	    /// A graphic clip at `at` on `track`, drawn by `graphics/<name>.js` at
59	    /// `width` × `height` (the canvas's when absent), five seconds long
60	    /// unless `duration` says otherwise, with `props` checked against
61	    /// `schema` when one is given (G-4). Fit scale, as a shape's box is.
62	    ///
63	    /// Refuses on an overlap-rule violation, in the rule's own sentence;
64	    /// `Err` for a bad name, a side outside 1–8192 (or a canvas side over
65	    /// it with no size given), a malformed schema, a bad prop, more than
66	    /// 64 props, an unknown track or a duration under a frame.
67	    #[allow(clippy::too_many_arguments)]
68	    pub fn add_graphic_clip(
69	        &self,
70	        track: u32,
71	        at: Ticks,
72	        duration: Option<Ticks>,
73	        name: &str,
74	        width: Option<u32>,
75	        height: Option<u32>,
76	        props: Option<&Value>,
77	        schema: Option<&Value>,
78	    ) -> Result<Outcome, String> {
79	        check_name(name)?;
80	        let width = self.graphic_side("width", width)?;
81	        let height = self.graphic_side("height", height)?;
82	        if let Some(schema) = schema {
83	            check_schema(schema)?;
84	        }
85	        let props = match props {
86	            None => Map::new(),
87	            Some(value) => {
88	                let patch = value.as_object().ok_or_else(|| {
89	                    format!("props must be a json object, not {}", describe(value))
90	                })?;
91	                let mut stored = check_props(patch, schema)?;
92	                stored.retain(|_, value| !value.is_null());
93	                check_count(&stored)?;
94	                stored
95	            }
96	        };
97	        // A graphic's size IS its source size, so an oversized one fits
98	        // like oversized footage does — the shape's rule.
99	        let scale = self.fit_scale(f64::from(width), f64::from(height));
100	        self.add_described_clip(
101	            track,
102	            at,
103	            duration,
104	            Described {
105	                source: Source::Graphic,
106	                scale,
107	                text: None,
108	                shape: None,
109	                graphic: Some(GraphicProps {
110	                    name: name.to_string(),
111	                    width,
112	                    height,
113	                    r#in: 0,
114	                    length: None,
115	                    props,
116	                }),
117	            },
118	        )
119	    }
