222	    /// Reads a `set_graphic` patch key by key, every value checked before
223	    /// any is applied, ticks snapped after their check.
224	    fn read_graphic_patch(
225	        &self,
226	        fields: &Map<String, Value>,
227	        schema: Option<&Value>,
228	    ) -> Result<GraphicPatch, String> {
229	        let mut read = GraphicPatch {
230	            name: None,
231	            width: None,
232	            height: None,
233	            length: None,
234	            props: None,
235	        };
236	        for (key, value) in fields {
237	            match key.as_str() {
238	                "name" => {
239	                    let name = value
240	                        .as_str()
241	                        .ok_or_else(|| format!("name must be a string, not {}", describe(value)))?;
242	                    check_name(name)?;
243	                    read.name = Some(name.to_string());
244	                }
245	                "width" | "height" => {
246	                    let side = value.as_u64().ok_or_else(|| {
247	                        format!("{key} must be a whole number, not {}", describe(value))
248	                    })?;
249	                    check_side(key, side)?;
250	                    // Inside 1–8192, so the narrowing cannot fail.
251	                    let side = u32::try_from(side).unwrap_or(GRAPHIC_MAX_SIDE);
252	                    if key == "width" {
253	                        read.width = Some(side);
254	                    } else {
255	                        read.height = Some(side);
256	                    }
257	                }
258	                "length" => read.length = Some(self.graphic_length(value)?),
259	                "props" => {
260	                    let patch = value.as_object().ok_or_else(|| {
261	                        format!("props must be a json object, not {}", describe(value))
262	                    })?;
263	                    read.props = Some(check_props(patch, schema)?);
264	                }
265	                "in" => {
266	                    return Err(
267	                        "\"in\" cannot be patched: trim_start and split own a graphic's in point"
268	                            .to_string(),
269	                    )
270	                }
271	                other => return Err(unknown_key(other, "a graphic patch")),
272	            }
273	        }
274	        Ok(read)
275	    }
