277	    /// `null` gives the length back to the clip's duration; a number is
278	    /// snapped to the nearest frame, and under one frame is an `Err` naming
279	    /// what was sent.
280	    fn graphic_length(&self, value: &Value) -> Result<Option<Ticks>, String> {
281	        if value.is_null() {
282	            return Ok(None);
283	        }
284	        let given = value.as_i64().ok_or_else(|| {
285	            format!(
286	                "length must be a whole number of ticks or null, not {}",
287	                describe(value)
288	            )
289	        })?;
290	        let snapped = self.snapped(given);
291	        if snapped < self.frame() {
292	            return Err(format!(
293	                "length must be at least one frame ({} ticks), not {given}",
294	                self.frame()
295	            ));
296	        }
297	        Ok(Some(snapped))
298	    }
299	}
300	//! The graphic vocabulary (format version 10, road map 10's G2a) —
301	//! [`GraphicProps`], what a graphic clip is drawn from, and the checks
302	//! every writer of one shares: the module name rule (G-3), the side bound,
303	//! the schema a module declares and the props checked against it (G-4),
304	//! whose `color` props are stored through `model_color.rs`'s CSS colour
305	//! normalisation (G-12) — and whose `color` DEFAULTS are checked by it too,
306	//! so a default G-12 refuses refuses the schema (G-25 (a)).
307	//!
308	//! A graphic is a source the model only DESCRIBES, as text and shape are.
309	//! The core never reads the module (it has no filesystem), so the schema a
310	//! patch is checked against is an ARGUMENT of the op, and without one only
311	//! the shape is checked. The checks are the core's own, over [`Value`]: no
312	//! module of the model may name the engine's crate (spec §11 G-2), so its
313	//! schema sentences are COPIED verbatim and its limits restated.
314	//!
315	//! **`props` keeps the caller's key order.** `serde_json`'s map is
316	//! insertion-ordered in this build (`core/Cargo.toml`), the file is read
317	//! back byte for byte, and under that feature `Map::remove` SWAPS the last
318	//! key into the hole. So a props map is only ever changed by `insert` (an
319	//! existing key keeps its slot, a new one is appended) and `shift_remove`.
320	//! The serde rules are `model.rs`'s.
