391	        .next()
392	        .is_some_and(|c| c.is_ascii_lowercase() || c.is_ascii_digit());
393	    let rest = chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-');
394	    if head && rest && name.len() <= 63 {
395	        Ok(())
396	    } else {
397	        Err(format!("graphic name \"{name}\" {NAME_RULE}"))
398	    }
