412	/// §5c's rules for a schema, each refused in the engine's own sentence
413	/// (its `props.rs`, copied verbatim).
414	pub(crate) fn check_schema(schema: &Value) -> Result<(), String> {
415	    let Some(entries) = schema.as_object() else {
416	        return Err("schema must be an object".to_string());
417	    };
418	    if entries.len() > GRAPHIC_MAX_PROPS {
419	        return Err(format!(
420	            "schema has {} keys; the most is {GRAPHIC_MAX_PROPS}",
421	            entries.len()
422	        ));
423	    }
424	    for (key, entry) in entries {
425	        check_entry(key, entry)?;
426	    }
427	    Ok(())
428	}
