430	fn check_entry(key: &str, entry: &Value) -> Result<(), String> {
431	    if !is_name(key) {
432	        return Err(format!(
433	            "schema key \"{key}\" is not a name (letters, digits and _, starting with a letter or _, at most 32 characters)"
434	        ));
435	    }
436	    let Some(kind) = entry.get("type").and_then(Value::as_str) else {
437	        return Err(format!("schema.{key} must be an object with a type"));
438	    };
439	    if !GRAPHIC_TYPES.contains(&kind) {
440	        return Err(format!(
441	            "schema.{key}.type \"{kind}\" is not one of string, number, boolean, color, enum, asset"
442	        ));
443	    }
444	    if kind == "enum" {
445	        let good = entry
446	            .get("options")
447	            .and_then(Value::as_array)
448	            .is_some_and(|o| {
449	                (1..=GRAPHIC_MAX_OPTIONS).contains(&o.len()) && o.iter().all(Value::is_string)
450	            });
451	        if !good {
452	            return Err(format!("schema.{key}.options must be 1–32 strings"));
453	        }
454	    }
455	    let Some(default) = entry.get("default") else {
456	        return Err(format!("schema.{key} has no default"));
457	    };
458	    let fits = match kind {
459	        "string" => default
460	            .as_str()
461	            .is_some_and(|s| s.chars().count() <= GRAPHIC_MAX_STRING),
462	        "color" => default.as_str().and_then(normalise_color).is_some(),
463	        "number" => default.as_f64().is_some_and(f64::is_finite),
464	        "boolean" => default.is_boolean(),
465	        "enum" => options(entry).contains(default),
466	        "asset" => default.is_string() || default.is_null(),
467	        _ => false,
468	    };
469	    if !fits {
470	        return Err(format!("schema.{key}.default {default} is not a {kind}"));
471	    }
472	    if let Some(animate) = entry.get("animate").filter(|a| !a.is_boolean()) {
473	        return Err(format!("schema.{key}.animate {animate} is not a boolean"));
474	    }
475	    Ok(())
476	}
