478	/// The engine's key rule, `^[A-Za-z_][A-Za-z0-9_]{0,31}$`.
479	fn is_name(key: &str) -> bool {
480	    let mut chars = key.chars();
481	    let head = chars
482	        .next()
483	        .is_some_and(|c| c.is_ascii_alphabetic() || c == '_');
484	    head && key.len() <= 32 && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
485	}
