495	/// A `props` patch checked key by key, answered as the copy to merge: each
496	/// `color` normalised, every `null` KEPT as a removal for the caller. With
497	/// a schema, each non-null key must be an entry and each value its type,
498	/// range and membership — a `null` is exempt, so a key stored before the
499	/// module dropped it can still be removed; without one only the shape is
500	/// checked. The key COUNT is
501	/// [`check_count`]'s, on the object about to be stored.
502	pub(crate) fn check_props(
503	    patch: &Map<String, Value>,
504	    schema: Option<&Value>,
505	) -> Result<Map<String, Value>, String> {
506	    let mut checked = Map::new();
507	    for (key, value) in patch {
508	        let value = match schema {
509	            // A removal is never checked, so a stale key can be cleared.
510	            Some(_) if value.is_null() => Value::Null,
511	            Some(schema) => {
512	                let Some(entry) = schema.get(key) else {
513	                    return Err(crate::patch::unknown_key(
514	                        &format!("props.{key}"),
515	                        "a graphic patch",
516	                    ));
517	                };
518	                check_typed(key, entry, value)?
519	            }
520	            None => {
521	                check_shape_only(key, value)?;
522	                value.clone()
523	            }
524	        };
525	        checked.insert(key.clone(), value);
526	    }
527	    Ok(checked)
528	}
