560	//! A graphic clip's own timeline (road map 10's G-9) and the layer source
561	//! the recipe publishes for one (spec §7.3).
562	//!
563	//! A graphic has a timeline of its own, counted in the graphic's frames:
564	//! the clip's first frame shows graphic time `in`, and the graphic runs for
565	//! `length` ticks, or — `length` null — until the clip ends, which is
566	//! graphic time `in + duration` (decision G-9·c). The module is asked for
567	//! one frame of that timeline, with a `ctx` saying where the frame falls in
568	//! the whole, and returns SVG; the app rasterizes it and caches the texture
569	//! by the `hash` published here.
570	//!
571	//! The arithmetic lives here, in ONE place, because it has writers and a
572	//! reader that must agree on it: `trim_start`, `roll`, `split`'s second
573	//! half and `add_transition`'s head move `in` through [`graphic_advanced`],
574	//! `split` pins both halves' `length` to [`effective_length`], every
575	//! re-snap through `frame_grid.rs` puts `in` and `length` on the new grid
576	//! through [`graphic_resnapped`] (G-18), and the recipe reads the same
577	//! [`effective_length`] for `durationInFrames`. An edit module importing a
578	//! read-side one has precedent (`edit_split.rs` reads `actions` and
579	//! `source_window`); the two natural homes, `model_graphic.rs` and
580	//! `source_window.rs`, stand at their caps.
581	//!
582	//! The `ctx` keys are exactly the engine's (road map 10 §5c) and the app
583	//! passes the object through verbatim, so a key renamed here is a key the
584	//! module never sees. The core never names the engine's crate (G-2), so the
585	//! shape is restated, and `core/tests/graphic.rs` holds it to a fixture.
586	
587	use serde_json::{Map, Value};
588	
589	use crate::actions::Evaluated;
590	use crate::evaluate::number;
591	use crate::model::{Canvas, Clip, GraphicProps, Project};
592	use crate::recipe::{content_hash, missing_source};
593	use crate::source_window::in_advanced;
594	use crate::time::{frame_index, snap_down_to_frame, snap_up_to_frame, Ticks};
595	
596	/// How long a graphic clip's own timeline is, in ticks, or `None` for a
597	/// clip that describes no graphic.
598	///
599	/// `length` when it is set; null means "it ends with the clip" (G-9), and
600	/// the clip ends at graphic time `in + duration` — not at `duration`, which
601	/// would make a front trim shorten the graphic's timeline and finish its
602	/// outro early while the clip still showed it (decision G-9·c). Under this
603	/// rule a front trim and a roll leave `durationInFrames` where it was.
604	pub(crate) fn effective_length(clip: &Clip) -> Option<Ticks> {
605	    clip.graphic.as_ref().map(|graphic| {
606	        graphic
607	            .length
608	            .unwrap_or(graphic.r#in.saturating_add(clip.duration))
609	    })
610	}
611	
612	/// `graphic` with its `in` advanced by `timeline` ticks, or `None` when
613	/// there is no graphic to move.
614	///
615	/// Through `source_window.rs`'s one mover at speed 1 (a graphic has no
616	/// speed), so `in` never goes below 0: a start dragged earlier than the
617	/// graphic's own first frame saturates there (decision G-9·a). Its four
618	/// callers are the front-trim writers: `trim_start`, `roll`, `split`'s
619	/// second half, and `add_transition`'s handle form, which moves `in` BACK
620	/// by the head it adds (G-18·a).
621	pub(crate) fn graphic_advanced(
622	    graphic: Option<&GraphicProps>,
623	    timeline: Ticks,
624	) -> Option<GraphicProps> {
625	    graphic.map(|graphic| {
626	        let mut moved = graphic.clone();
627	        moved.r#in = in_advanced(graphic.r#in, timeline, 1.0);
628	        moved
629	    })
630	}
631	
632	/// `graphic` on `project`'s frame grid, or `None` when there is no graphic
633	/// — what every re-snap through `frame_grid.rs` writes (G-18·b). `in` is
634	/// the canvas's frames, not a source position, so it snaps to the nearest
635	/// frame, never below 0; a set `length` snaps with `set_graphic`'s
636	/// one-frame floor, and a null one stays null.
637	pub(crate) fn graphic_resnapped(
638	    graphic: Option<&GraphicProps>,
639	    project: &Project,
640	) -> Option<GraphicProps> {
641	    graphic.map(|graphic| {
642	        let mut snapped = graphic.clone();
643	        snapped.r#in = project.snapped(graphic.r#in).max(0);
644	        snapped.length = graphic
645	            .length
646	            .map(|length| project.snapped(length).max(project.frame()));
647	        snapped
648	    })
649	}
