121	    /// Patches each named graphic clip's `name`, `width`, `height`,
122	    /// `length` and `props` (road map 10 §5h). `props` merges key by key and
123	    /// a `null` removes its key — except, with a `schema`, a prop an action
124	    /// on the clip names, which takes the schema's default (G-34 (d)); `in`
125	    /// is not patchable, because the trims and `split` own it (G-9).
126	    ///
127	    /// `Err` for a malformed schema, a patch that is not an object, an
128	    /// unknown clip, a clip that is not a graphic, an unknown key and any
129	    /// value its check refuses; an identity when nothing changes — a colour
130	    /// re-sent in another spelling included. No rule refuses a patch, as
131	    /// none refuses `set_shape`'s.
132	    pub fn set_graphic(
133	        &self,
134	        clips: &[u32],
135	        patch: &Value,
136	        schema: Option<&Value>,
137	    ) -> Result<Outcome, String> {
138	        if let Some(schema) = schema {
139	            check_schema(schema)?;
140	        }
141	        let Some(fields) = patch.as_object() else {
142	            return Err(format!(
143	                "graphic patch must be a json object, not {}",
144	                describe(patch)
145	            ));
146	        };
147	        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();
148	        if ids.is_empty() {
149	            return Ok(Outcome::Identity);
150	        }
151	        for id in &ids {
152	            let clip = self.require_clip(*id)?;
153	            if !(matches!(clip.source, Source::Graphic) && clip.graphic.is_some()) {
154	                return Err(format!("clip {id} is not a graphic clip"));
155	            }
156	        }
157	        let read = self.read_graphic_patch(fields, schema)?;
158	
159	        let mut next = self.clone();
160	        for id in ids {
161	            let Some(original) = self.clip(id) else {
162	                continue;
163	            };
164	            let Some(graphic) = next.clip_mut(id).and_then(|clip| clip.graphic.as_mut()) else {
165	                continue;
166	            };
167	            if let Some(name) = &read.name {
168	                graphic.name = name.clone();
169	            }
170	            if let Some(width) = read.width {
171	                graphic.width = width;
172	            }
173	            if let Some(height) = read.height {
174	                graphic.height = height;
175	            }
176	            if let Some(length) = read.length {
177	                graphic.length = length;
178	            }
179	            if let Some(props) = &read.props {
180	                for (key, value) in props {
181	                    let kept = schema
182	                        .and_then(|schema| schema_default(schema, key))
183	                        .filter(|_| value.is_null() && names_prop(original, key));
184	                    if let Some(default) = kept {
185	                        graphic.props.insert(key.clone(), default);
186	                    } else if value.is_null() {
187	                        graphic.props.shift_remove(key);
188	                    } else {
189	                        graphic.props.insert(key.clone(), value.clone());
190	                    }
191	                }
192	                check_count(&graphic.props)?;
193	            }
194	        }
195	        self.finish(next)
196	    }
