651	/// A graphic layer's `source` and `source_size` at `clip_t` ticks into the
652	/// clip, on `canvas` — the PROJECT's canvas, inside a nest too (§5c).
653	///
654	/// The frame is FLOORED onto the grid (a tick inside a frame shows that
655	/// frame) and `durationInFrames` is CEILED (a partial last frame still
656	/// draws); `progress` runs 0 to 1 over the graphic's frames and clamps, so
657	/// a clip held past its graphic's `length` shows the last state. Every
658	/// float passes through `number`, so a degenerate rate publishes 0 and
659	/// never a non-finite value.
660	///
661	/// The `hash` covers everything the module is called with — the name, the
662	/// frame, the whole `ctx` and the props (decision G-9·b): a `trim_end`
663	/// changes `durationInFrames` and so the outro at the same frame, and a
664	/// rate change changes `time`, so a key over less would serve a stale
665	/// texture. The props are the map EVALUATED at `clip_t`
666	/// ([`Evaluated::graphic`], spec §11 G-34): the stored map with each
667	/// finished action's `graphic.props` laid over it and the spanning one's
668	/// interpolated, which is the stored map itself when no action names a
669	/// prop, so such a layer's hash is what it always was. `content_hash` sorts
670	/// keys, so their order does not move the hash.
671	pub(crate) fn graphic_source(
672	    clip: &Clip,
673	    evaluated: &Evaluated,
674	    clip_t: Ticks,
675	    canvas: &Canvas,
676	) -> (Value, Value) {
677	    let (Some(graphic), Some(effective)) = (clip.graphic.as_ref(), effective_length(clip)) else {
678	        return (missing_source(), Value::Null);
679	    };
680	    let fps = canvas.fps;
681	    let rate = fps.as_f64();
682	    let at = graphic.r#in.saturating_add(clip_t);
683	    let frame = frame_index(snap_down_to_frame(at, fps), fps).unwrap_or(0);
684	    let frames = frame_index(snap_up_to_frame(effective, fps), fps).unwrap_or(0);
685	    let progress = (frame as f64 / frames.saturating_sub(1).max(1) as f64).clamp(0.0, 1.0);
686	
687	    let mut size = Map::new();
688	    size.insert("width".to_string(), Value::from(canvas.width));
689	    size.insert("height".to_string(), Value::from(canvas.height));
690	    let mut ctx = Map::new();
691	    ctx.insert("fps".to_string(), number(rate));
692	    ctx.insert("time".to_string(), number(frame as f64 / rate));
693	    ctx.insert("durationInFrames".to_string(), Value::from(frames));
694	    ctx.insert("progress".to_string(), number(progress));
695	    ctx.insert("width".to_string(), Value::from(graphic.width));
696	    ctx.insert("height".to_string(), Value::from(graphic.height));
697	    ctx.insert("canvas".to_string(), Value::Object(size));
698	    let ctx = Value::Object(ctx);
699	    let props = Value::Object(evaluated.graphic.as_ref().map_or_else(
700	        || graphic.props.clone(),
701	        |evaluated| evaluated.props.clone(),
702	    ));
703	    let ctx_json = serde_json::to_string(&ctx).unwrap_or_default();
704	    let props_json = serde_json::to_string(&props).unwrap_or_default();
705	
706	    let mut called = Map::new();
707	    called.insert("name".to_string(), Value::from(graphic.name.as_str()));
708	    called.insert("frame".to_string(), Value::from(frame));
709	    called.insert("ctx".to_string(), ctx.clone());
710	    called.insert("props".to_string(), props.clone());
711	    let hash = content_hash(&Value::Object(called));
712	
713	    let mut source = Map::new();
714	    source.insert("kind".to_string(), Value::from("graphic"));
715	    source.insert("name".to_string(), Value::from(graphic.name.as_str()));
716	    source.insert("hash".to_string(), Value::from(hash));
717	    source.insert("frame".to_string(), Value::from(frame));
718	    source.insert("ctx".to_string(), ctx);
719	    source.insert("props".to_string(), props);
720	    source.insert("props_json".to_string(), Value::String(props_json));
721	    source.insert("ctx_json".to_string(), Value::String(ctx_json));
722	    let source_size = Value::Array(vec![
723	        Value::from(graphic.width),
724	        Value::from(graphic.height),
725	    ]);
726	    (Value::Object(source), source_size)
727	}
